let data = $json;
if (typeof $json.output === 'string') {
  try { data = JSON.parse($json.output); } catch(e) {}
} else if ($json.output && typeof $json.output === 'object') {
  data = $json.output;
}

const phone = $('WF-DPV.02 - TRIGGER | Iniciar Extracao').item.json.phone;
const messageId = $('WF-DPV.02 - TRIGGER | Iniciar Extracao').item.json.messageId;

const valor = parseFloat(data.valor_total) || 0;
const dataEmissao = data.data_emissao || null;
const confianca = parseFloat(data.confianca) || 0;

const erros = [];
if (valor <= 0) erros.push('Valor deve ser maior que zero');
if (valor > 999999.99) erros.push('Valor acima do limite');

if (dataEmissao) {
  const d = new Date(dataEmissao + 'T00:00:00');
  const hoje = new Date();
  const limite90 = new Date();
  limite90.setDate(hoje.getDate() - 90);
  if (d > hoje) erros.push('Data futura nao permitida');
  if (d < limite90) erros.push('Data muito antiga (mais de 90 dias)');
}

const valido = erros.length === 0;
const motivoErro = valido ? null : erros.join(' | ');

const itensRaw = Array.isArray(data.itens_json) ? data.itens_json : [];

const dadosExtraidos = {
  estabelecimento: data.estabelecimento || null,
  cnpj: data.cnpj || null,
  valor_total: valor,
  data_emissao: dataEmissao,
  categoria: data.categoria || 'outros',
  forma_pagamento_nf: data.forma_pagamento || null,
  tipo_pagador_nf: data.tipo_pagador || null,
  cpf_cnpj_pagador_nf: data.cpf_cnpj_pagador || null,
  confianca,
  observacoes_modelo: data.observacoes_modelo || null,
  itens: itensRaw
};

return [{
  json: {
    phone,
    message_id: messageId,
    valor_total: valor,
    validacao_ok: valido,
    motivo_erro: motivoErro,
    dados_extraidos_str: JSON.stringify(dadosExtraidos).replace(/'/g, "''")
  }
}];

